/**
 * Aptitude practice questions, the kind placement tests and screening rounds ask (quantitative, logical, verbal).
 * Quantitative and logical questions are generated by code from random numbers, and their answers are computed, so
 * the key is always right and every test is fresh. Verbal questions come from a small hand-checked bank.
 */

export type Section = "quant" | "logical" | "verbal";
export interface Question { id: string; section: Section; topic: string; prompt: string; options: string[]; answer: number; explain: string }

export const SECTIONS: { id: Section; label: string; about: string }[] = [
  { id: "quant", label: "Quantitative", about: "Percentages, profit and loss, ratios, time and work, speed, interest, averages." },
  { id: "logical", label: "Logical reasoning", about: "Number series, coding-decoding, directions, odd one out." },
  { id: "verbal", label: "Verbal ability", about: "Synonyms, antonyms and sentence correction." },
];

/** A small seeded random generator (mulberry32), so a test can be replayed from its seed. */
export function rng(seed: number) {
  let a = seed >>> 0;
  const next = () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const int = (lo: number, hi: number) => lo + Math.floor(next() * (hi - lo + 1));
  const pick = <T,>(xs: readonly T[]): T => xs[Math.floor(next() * xs.length)]!;
  const shuffle = <T,>(xs: T[]): T[] => { const a2 = [...xs]; for (let i = a2.length - 1; i > 0; i--) { const j = Math.floor(next() * (i + 1)); [a2[i], a2[j]] = [a2[j]!, a2[i]!]; } return a2; };
  return { next, int, pick, shuffle };
}
type R = ReturnType<typeof rng>;

/** Four options: the right one and three distinct distractors, shuffled. */
function mcq(r: R, right: string, wrong: string[]): { options: string[]; answer: number } {
  const uniq = [...new Set(wrong.filter((w) => w !== right))].slice(0, 3);
  let k = 1;
  while (uniq.length < 3) { const filler = `${right} (${k++})`; if (!uniq.includes(filler)) uniq.push(filler); }
  const options = r.shuffle([right, ...uniq]);
  return { options, answer: options.indexOf(right) };
}
const n = (x: number) => (Number.isInteger(x) ? x.toLocaleString("en-IN") : x.toLocaleString("en-IN", { maximumFractionDigits: 2 }));

type Gen = (r: R) => Omit<Question, "id" | "section">;

const QUANT: Gen[] = [
  (r) => { const p = r.pick([5, 10, 12, 15, 20, 25, 30, 40]), base = r.int(4, 40) * 50, ans = (p * base) / 100;
    return { topic: "Percentages", prompt: `What is ${p}% of ${n(base)}?`, ...mcq(r, n(ans), [n(ans * 2), n(ans / 2), n(ans + base / 10), n(ans + p)]), explain: `${p}% of ${n(base)} = ${p}/100 × ${n(base)} = ${n(ans)}.` }; },
  (r) => { const cost = r.int(4, 40) * 50, p = r.pick([10, 15, 20, 25, 30]), sell = (cost * (100 + p)) / 100;
    return { topic: "Profit and loss", prompt: `An item bought for ₹${n(cost)} is sold for ₹${n(sell)}. What is the profit percentage?`, ...mcq(r, `${p}%`, [`${p + 5}%`, `${p - 5}%`, `${Math.round(((sell - cost) / sell) * 100)}%`]), explain: `Profit = ₹${n(sell - cost)}. Profit % = ${n(sell - cost)} / ${n(cost)} × 100 = ${p}% (always on the cost price).` }; },
  (r) => { const a = r.int(2, 9), b = r.int(2, 9), unit = r.int(5, 30), total = (a + b) * unit;
    return { topic: "Ratios", prompt: `₹${n(total)} is shared between A and B in the ratio ${a}:${b}. How much does A get?`, ...mcq(r, `₹${n(a * unit)}`, [`₹${n(b * unit)}`, `₹${n(total / 2)}`, `₹${n((a + 1) * unit)}`]), explain: `Total parts = ${a + b}. One part = ${n(total)} / ${a + b} = ${n(unit)}. A gets ${a} × ${n(unit)} = ₹${n(a * unit)}.` }; },
  (r) => { const [x, y] = r.pick([[6, 3], [12, 6], [10, 15], [12, 4], [20, 30], [15, 10], [8, 24], [9, 18]] as const), d = (x * y) / (x + y);
    return { topic: "Time and work", prompt: `A can finish a job in ${x} days and B in ${y} days. Working together, how many days do they take?`, ...mcq(r, `${n(d)} days`, [`${n((x + y) / 2)} days`, `${n(x + y)} days`, `${n(Math.abs(x - y) || d + 2)} days`]), explain: `Together they do 1/${x} + 1/${y} = ${x + y}/${x * y} of the job a day, so they need ${x * y}/${x + y} = ${n(d)} days.` }; },
  (r) => { const kmh = r.pick([36, 54, 72, 90, 108]), ms = (kmh * 5) / 18, t = r.int(5, 20), len = ms * t;
    return { topic: "Speed and distance", prompt: `A train running at ${kmh} km/h passes a pole in ${t} seconds. How long is the train?`, ...mcq(r, `${n(len)} m`, [`${n(kmh * t)} m`, `${n(len / 2)} m`, `${n(len + 50)} m`]), explain: `${kmh} km/h = ${kmh} × 5/18 = ${n(ms)} m/s. Length = speed × time = ${n(ms)} × ${t} = ${n(len)} m.` }; },
  (r) => { const p = r.int(2, 20) * 1000, rate = r.pick([5, 6, 8, 10, 12]), yrs = r.int(2, 5), si = (p * rate * yrs) / 100;
    return { topic: "Simple interest", prompt: `What is the simple interest on ₹${n(p)} at ${rate}% a year for ${yrs} years?`, ...mcq(r, `₹${n(si)}`, [`₹${n(si / yrs)}`, `₹${n(si + p)}`, `₹${n((p * rate) / 100 + 100)}`]), explain: `SI = P × R × T / 100 = ${n(p)} × ${rate} × ${yrs} / 100 = ₹${n(si)}.` }; },
  (r) => { const k = r.int(4, 6), xs = Array.from({ length: k }, () => r.int(10, 90)), sum = xs.reduce((a, b) => a + b, 0), avg = sum / k;
    return { topic: "Averages", prompt: `What is the average of ${xs.join(", ")}?`, ...mcq(r, n(avg), [n(avg + 2), n(avg - 3), n(sum / (k - 1))]), explain: `Sum = ${sum}, count = ${k}. Average = ${sum} / ${k} = ${n(avg)}.` }; },
  (r) => { const price = r.int(4, 30) * 100, a = r.pick([10, 20, 25]), b = r.pick([10, 20]), final = price * (1 - a / 100) * (1 - b / 100), single = 100 - (final / price) * 100;
    return { topic: "Successive discounts", prompt: `Two successive discounts of ${a}% and ${b}% equal a single discount of how much?`, ...mcq(r, `${n(single)}%`, [`${a + b}%`, `${n(single + 2)}%`, `${Math.abs(a - b) || a}%`]), explain: `Price left = (1 − ${a}/100) × (1 − ${b}/100) = ${n((final / price) * 100)}% of the original, so the single discount is ${n(single)}%.` }; },
];

const LOGICAL: Gen[] = [
  (r) => { const a = r.int(2, 20), d = r.int(3, 12), xs = Array.from({ length: 5 }, (_, i) => a + i * d), next = a + 5 * d;
    return { topic: "Number series", prompt: `Find the next number: ${xs.join(", ")}, ?`, ...mcq(r, String(next), [String(next + d), String(next - 1), String(next + 2)]), explain: `Each number adds ${d}, so the next is ${xs[4]} + ${d} = ${next}.` }; },
  (r) => { const a = r.int(2, 5), q = r.pick([2, 3]), xs = Array.from({ length: 5 }, (_, i) => a * q ** i), next = a * q ** 5;
    return { topic: "Number series", prompt: `Find the next number: ${xs.join(", ")}, ?`, ...mcq(r, String(next), [String(next + a), String(xs[4]! * 2 + 1), String(next - q)]), explain: `Each number is multiplied by ${q}: ${xs[4]} × ${q} = ${next}.` }; },
  (r) => { const s = r.int(1, 6), xs = Array.from({ length: 5 }, (_, i) => (s + i) ** 2), next = (s + 5) ** 2;
    return { topic: "Number series", prompt: `Find the next number: ${xs.join(", ")}, ?`, ...mcq(r, String(next), [String(next + 1), String(next - (s + 5)), String(xs[4]! + 2 * (s + 4))]), explain: `These are squares of ${s} to ${s + 4}, so next is ${s + 5}² = ${next}.` }; },
  (r) => { const shift = r.int(1, 4), words = ["WATER", "PLANT", "CLOUD", "MONEY", "TRAIN", "SMILE", "BRAIN", "LIGHT"], [w1, w2] = r.shuffle(words).slice(0, 2) as [string, string];
    const enc = (w: string, k: number) => w.replace(/[A-Z]/g, (c) => String.fromCharCode(((c.charCodeAt(0) - 65 + k + 26) % 26) + 65));
    return { topic: "Coding-decoding", prompt: `If ${w1} is written as ${enc(w1, shift)}, how is ${w2} written in that code?`, ...mcq(r, enc(w2, shift), [enc(w2, shift + 1), enc(w2, -shift), enc(w2, shift).split("").reverse().join("")]), explain: `Each letter moves ${shift} place${shift === 1 ? "" : "s"} forward in the alphabet, so ${w2} becomes ${enc(w2, shift)}.` }; },
  (r) => { const steps = [r.int(2, 9), r.int(2, 9), r.int(2, 9)];
    // North, turn right (East), turn right (South).
    const x = steps[1]!, y = steps[0]! - steps[2]!, dist = Math.hypot(x, y), ns = y > 0 ? "north" : y < 0 ? "south" : "", dir = [ns, "east"].filter(Boolean).join("-");
    const right = Number.isInteger(dist) ? `${dist} km` : `√${x * x + y * y} km`;
    return { topic: "Directions", prompt: `Ravi walks ${steps[0]} km north, turns right and walks ${steps[1]} km, then turns right again and walks ${steps[2]} km. How far is he from where he started, in a straight line?`, ...mcq(r, right, [`${steps[0]! + steps[1]! + steps[2]!} km`, `${x} km`, `${Math.abs(y) + x} km`]), explain: `He ends ${x} km east and ${Math.abs(y)} km ${ns || "level with the start"}${dir ? ` (${dir})` : ""}. Distance = √(${x}² + ${Math.abs(y)}²) = ${right}.` }; },
  (r) => { const sets = [["Apple", "Mango", "Banana", "Carrot"], ["Delhi", "Mumbai", "Kolkata", "Nepal"], ["Copper", "Iron", "Silver", "Plastic"], ["Python", "Java", "Rust", "Excel"], ["Tiger", "Lion", "Leopard", "Wolf"], ["Square", "Triangle", "Circle", "Cube"]] as const;
    const set = r.pick(sets), odd = set[3], reasons: Record<string, string> = { Carrot: "a vegetable; the rest are fruits", Nepal: "a country; the rest are Indian cities", Plastic: "not a metal", Excel: "a spreadsheet app, not a programming language", Wolf: "not a big cat", Cube: "a 3D shape; the rest are flat" };
    const options = r.shuffle([...set]);
    return { topic: "Odd one out", prompt: `Which one does not belong?`, options, answer: options.indexOf(odd), explain: `${odd} is ${reasons[odd]}.` }; },
];

const VERBAL: Omit<Question, "id" | "section">[] = [
  { topic: "Synonyms", prompt: "Choose the word closest in meaning to ABUNDANT.", options: ["Plentiful", "Scarce", "Hidden", "Brief"], answer: 0, explain: "Abundant means existing in large quantities: plentiful." },
  { topic: "Synonyms", prompt: "Choose the word closest in meaning to CANDID.", options: ["Frank", "Shy", "Sweet", "Careful"], answer: 0, explain: "Candid means honest and straightforward: frank." },
  { topic: "Synonyms", prompt: "Choose the word closest in meaning to METICULOUS.", options: ["Careless", "Thorough", "Quick", "Noisy"], answer: 1, explain: "Meticulous means showing great attention to detail: thorough." },
  { topic: "Synonyms", prompt: "Choose the word closest in meaning to OBSOLETE.", options: ["Modern", "Outdated", "Useful", "Rare"], answer: 1, explain: "Obsolete means no longer in use: outdated." },
  { topic: "Synonyms", prompt: "Choose the word closest in meaning to DILIGENT.", options: ["Lazy", "Hardworking", "Clever", "Angry"], answer: 1, explain: "Diligent means showing care and effort in work: hardworking." },
  { topic: "Synonyms", prompt: "Choose the word closest in meaning to CONCISE.", options: ["Brief", "Lengthy", "Confusing", "Loud"], answer: 0, explain: "Concise means giving information clearly in few words: brief." },
  { topic: "Antonyms", prompt: "Choose the word most opposite in meaning to TRANSPARENT.", options: ["Clear", "Opaque", "Thin", "Bright"], answer: 1, explain: "Transparent lets light through; opaque does not." },
  { topic: "Antonyms", prompt: "Choose the word most opposite in meaning to EXPAND.", options: ["Grow", "Contract", "Spread", "Open"], answer: 1, explain: "Expand means become larger; contract means become smaller." },
  { topic: "Antonyms", prompt: "Choose the word most opposite in meaning to ANCIENT.", options: ["Old", "Historic", "Modern", "Famous"], answer: 2, explain: "Ancient means very old; modern means recent." },
  { topic: "Antonyms", prompt: "Choose the word most opposite in meaning to GENEROUS.", options: ["Kind", "Selfish", "Rich", "Friendly"], answer: 1, explain: "Generous means willing to give; selfish means unwilling to share." },
  { topic: "Antonyms", prompt: "Choose the word most opposite in meaning to OPTIMISTIC.", options: ["Hopeful", "Cheerful", "Pessimistic", "Confident"], answer: 2, explain: "Optimistic expects good outcomes; pessimistic expects bad ones." },
  { topic: "Antonyms", prompt: "Choose the word most opposite in meaning to RIGID.", options: ["Flexible", "Strong", "Hard", "Fixed"], answer: 0, explain: "Rigid means unable to bend; flexible means able to bend." },
  { topic: "Sentence correction", prompt: "Choose the correct sentence.", options: ["Each of the students have a laptop.", "Each of the students has a laptop.", "Each of the students having a laptop.", "Each of the student has a laptop."], answer: 1, explain: "\"Each\" is singular, so it takes \"has\", and \"of the students\" stays plural." },
  { topic: "Sentence correction", prompt: "Choose the correct sentence.", options: ["She is senior than me.", "She is senior to me.", "She is more senior than I.", "She is senior from me."], answer: 1, explain: "\"Senior\", \"junior\" and \"prior\" take \"to\", not \"than\"." },
  { topic: "Sentence correction", prompt: "Choose the correct sentence.", options: ["I am working here since 2021.", "I have been working here since 2021.", "I was working here since 2021.", "I work here since 2021."], answer: 1, explain: "An action that started in the past and continues uses the present perfect continuous with \"since\"." },
  { topic: "Sentence correction", prompt: "Choose the correct sentence.", options: ["Neither the manager nor the employees was present.", "Neither the manager nor the employees were present.", "Neither the manager or the employees were present.", "Neither the manager nor the employees is present."], answer: 1, explain: "With \"neither … nor\", the verb agrees with the nearer subject, \"employees\": were." },
  { topic: "Sentence correction", prompt: "Choose the correct sentence.", options: ["He discussed about the project.", "He discussed the project.", "He discussed on the project.", "He discussed over the project."], answer: 1, explain: "\"Discuss\" takes a direct object; no preposition follows it." },
  { topic: "Sentence correction", prompt: "Choose the correct sentence.", options: ["Please revert back by Friday.", "Please reply by Friday.", "Please revert by Friday back.", "Please return back by Friday."], answer: 1, explain: "\"Revert\" means go back to a previous state; in business English, \"reply\" is what's meant, and \"back\" is redundant." },
];

/** A test of `count` questions from the chosen sections, reproducible from `seed`. */
export function buildTest(sections: Section[], count: number, seed: number): Question[] {
  const r = rng(seed);
  const out: Question[] = [];
  const pools: Record<Section, () => Omit<Question, "id" | "section">> = {
    quant: () => r.pick(QUANT)(r),
    logical: () => r.pick(LOGICAL)(r),
    verbal: (() => { const bank = r.shuffle(VERBAL); let i = 0; return () => { const q = bank[i++ % bank.length]!; const order = r.shuffle([0, 1, 2, 3]); return { ...q, options: order.map((k) => q.options[k]!), answer: order.indexOf(q.answer) }; }; })(),
  };
  for (let i = 0; i < count; i++) {
    const section = sections[i % sections.length]!;
    out.push({ id: `${seed}-${i}`, section, ...pools[section]() });
  }
  return r.shuffle(out);
}
